/bin/zsh -lc "rtk python3 - <<'PY'
import json
from pathlib import Path
paths = [
'QA/CHG-232/map_geometry.json', 'QA/final_cross_browser.json',
'QA/CHG-232/phone_field_surface.json', 'QA/CHG-232/portability.json',
'QA/CHG-232/release/gate4_runtime.json', 'QA/CHG-232/release/fast.json',
'QA/CHG-232/release/qualification.json',
]
keys = {'status','candidate_head','candidate_tree','expected_revision','actual_revision','revision','source_sha','source_tree','commit','tree','source_binding','candidate_sha','head','tree_sha','runtime'}
targets = {'map_geometry','cross_browser','phone_field_surface','portability','gate4_runtime','fast'}
def walk(x):
    if isinstance(x, dict):
        if x.get('name') in targets:
            yield {k:v for k,v in x.items() if k in keys or k in {'name','evidence','returncode','execution_status'}}
        for v in x.values(): yield from walk(v)
    elif isinstance(x, list):
        for v in x: yield from walk(v)
for name in paths:
    p=Path(name)
    if not p.exists():
        print(f'{name}: MISSING'); continue
    d=json.loads(p.read_text())
    print(f'--- {name} ---')
    if isinstance(d, dict):
        print('top:', {k:v for k,v in d.items() if k in keys or k in {'tests','failures','errors','checks','components'}})
    for row in walk(d): print('component:', row)
